-- ** Account
-- | Account
-- User account model containing properties related to a user's account.
data Account = Account
  { accountAbout :: !(Maybe Text) -- ^ "about" - Profile about description.
  , accountAccountType :: !(Maybe UserAccountType) -- ^ "account_type" - Type of account
  , accountBoardCount :: !(Maybe Int) -- ^ /ReadOnly/ "board_count" -   User account board count.   **Note**: Board count on user account level may differ from counts found elsewhere due to attribution of collaborative Boards.
  , accountBusinessName :: !(Maybe Text) -- ^ "business_name"
  , accountFollowerCount :: !(Maybe Int) -- ^ /ReadOnly/ "follower_count" - User account follower count.
  , accountFollowingCount :: !(Maybe Int) -- ^ /ReadOnly/ "following_count" - User account following count.
  , accountId :: !(Maybe Text) -- ^ "id" - User account ID.
  , accountMonthlyViews :: !(Maybe Int) -- ^ /ReadOnly/ "monthly_views" - User account monthly views.
  , accountPinCount :: !(Maybe Int) -- ^ /ReadOnly/ "pin_count" - User account pin count. This includes both created and saved pins.
  , accountProfileImage :: !(Maybe Text) -- ^ "profile_image"
  , accountUsername :: !(Maybe Text) -- ^ "username"
  , accountWebsiteUrl :: !(Maybe Text) -- ^ "website_url"
  } deriving (P.Show, P.Eq, P.Typeable)

-- | FromJSON Account
instance A.FromJSON Account where
  parseJSON = A.withObject "Account" $ \o ->
    Account
      <$> (o .:? "about")
      <*> (o .:? "account_type")
      <*> (o .:? "board_count")
      <*> (o .:? "business_name")
      <*> (o .:? "follower_count")
      <*> (o .:? "following_count")
      <*> (o .:? "id")
      <*> (o .:? "monthly_views")
      <*> (o .:? "pin_count")
      <*> (o .:? "profile_image")
      <*> (o .:? "username")
      <*> (o .:? "website_url")

-- | ToJSON Account
instance A.ToJSON Account where
  toJSON Account {..} =
   _omitNulls
      [ "about" .= accountAbout
      , "account_type" .= accountAccountType
      , "board_count" .= accountBoardCount
      , "business_name" .= accountBusinessName
      , "follower_count" .= accountFollowerCount
      , "following_count" .= accountFollowingCount
      , "id" .= accountId
      , "monthly_views" .= accountMonthlyViews
      , "pin_count" .= accountPinCount
      , "profile_image" .= accountProfileImage
      , "username" .= accountUsername
      , "website_url" .= accountWebsiteUrl
      ]


-- | Construct a value of type 'Account' (by applying it's required fields, if any)
mkAccount
  :: Account
mkAccount =
  Account
  { accountAbout = Nothing
  , accountAccountType = Nothing
  , accountBoardCount = Nothing
  , accountBusinessName = Nothing
  , accountFollowerCount = Nothing
  , accountFollowingCount = Nothing
  , accountId = Nothing
  , accountMonthlyViews = Nothing
  , accountPinCount = Nothing
  , accountProfileImage = Nothing
  , accountUsername = Nothing
  , accountWebsiteUrl = Nothing
  }

