data AccountTemplate = AccountTemplate
  { accountTemplateAdAccountId :: !(Maybe Text) -- ^ /ReadOnly/ "ad_account_id" - ID of the Ad Account that owns the template
  , accountTemplateAdAccountIds :: !(Maybe [Text]) -- ^ "ad_account_ids" - IDs of the Ad Accounts that have access to this template
  , accountTemplateAdeColumns :: !(Maybe [Text]) -- ^ "ade_columns" - A list of ADE columns
  , accountTemplateAttributionType :: !(Maybe AnyType) -- ^ "attribution_type" - Attribution type for Brand/Category/SKU reports
  , accountTemplateClickWindowDays :: !(Maybe Double) -- ^ "click_window_days" - The length of the sliding window over which click conversions will be attributed
  , accountTemplateColumns :: !(Maybe [ReportingColumn]) -- ^ "columns" - A list of columns to be included in the report
  , accountTemplateConversionReportTimeType :: !(Maybe ConversionReportTimeType) -- ^ "conversion_report_time_type" - Conversion report time type
  , accountTemplateCreationSource :: !(Maybe CreationSource) -- ^ "creation_source" - The surface used to create this template
  , accountTemplateCustomColumnIds :: !(Maybe [Text]) -- ^ "custom_column_ids" - A list of custom column IDs
  , accountTemplateDisplayMetadata :: !(Maybe Text) -- ^ "display_metadata" - Additional metadata about this reporting template
  , accountTemplateEngagementWindowDays :: !(Maybe Double) -- ^ "engagement_window_days" - The length of the sliding window over which engagement conversions will be attributed
  , accountTemplateFiltersJson :: !(Maybe Text) -- ^ "filters_json" - A JSON representation of any filters to be applied before returning report data. Each filter object should contain all of the following fields:\\ \&quot;field\&quot;: The column name\\ \&quot;operator\&quot;: The operator. Allowed operators: [\&quot;&#x3D;\&quot;, \&quot;!&#x3D;\&quot;, \&quot;in\&quot;, \&quot;not_in\&quot;, \&quot;~\&quot;, \&quot;&gt;\&quot;, \&quot;&lt;\&quot;, \&quot;contains_substring\&quot;]\\ \&quot;value\&quot;: A single value or a list of values
  , accountTemplateGranularity :: !(Maybe Granularity) -- ^ "granularity"
  , accountTemplateId :: !(Text) -- ^ /Required/ /ReadOnly/ "id" - Template ID
  , accountTemplateIngestionSources :: !(Maybe [IngestionSource]) -- ^ "ingestion_sources" - The filter on the conversion ingestion source method for conversion metrics
  , accountTemplateIsDefault :: !(Maybe Bool) -- ^ "is_default" - A boolean representing if this is the default view that loads for this template type
  , accountTemplateIsDeleted :: !(Maybe Bool) -- ^ "is_deleted" - A boolean that indicates if the template has been deleted
  , accountTemplateIsOwnedByUser :: !(Maybe Bool) -- ^ "is_owned_by_user" - A boolean value that indicates if the user owns the template
  , accountTemplateIsScheduled :: !(Maybe Bool) -- ^ "is_scheduled" - A boolean value that indicates if this template has been used to create a scheduled report
  , accountTemplateName :: !(Maybe Text) -- ^ "name" - Template Name
  , accountTemplateReportEndRelativeDaysInPast :: !(Maybe Double) -- ^ "report_end_relative_days_in_past" - The number of days prior to the day the report will be delivered at which the report will end
  , accountTemplateReportFormat :: !(Maybe DataOutputFormat) -- ^ "report_format"
  , accountTemplateReportLevel :: !(Maybe MetricsReportingLevel) -- ^ "report_level"
  , accountTemplateReportStartRelativeDaysInPast :: !(Maybe Double) -- ^ "report_start_relative_days_in_past" - The number of days prior to the day the report will be delivered at which the report will start
  , accountTemplateReportingTimeZone :: !(Maybe ReportingTimeZone) -- ^ "reporting_time_zone" - Timezone for reporting data
  , accountTemplateSortBy :: !(Maybe AnyType) -- ^ "sort_by" - Unified metric sort configuration
  , accountTemplateType :: !(Maybe Text) -- ^ "type" - Type of the template
  , accountTemplateUpdatedTime :: !(Maybe Double) -- ^ /ReadOnly/ "updated_time" - Time of last update in seconds since Unix epoch
  , accountTemplateUserId :: !(Maybe Text) -- ^ "user_id" - ID of the user who created the template
  , accountTemplateViewWindowDays :: !(Maybe Double) -- ^ "view_window_days" - The length of the sliding window over which view conversions will be attributed
  } deriving (P.Show, P.Eq, P.Typeable)

