-- ** Ad
-- | Ad
data Ad = Ad
  { adAdAccountId :: !(Text) -- ^ /Required/ /ReadOnly/ "ad_account_id" - The ID of the advertiser that this ad belongs to.
  , adAdGroupId :: !(Text) -- ^ /Required/ "ad_group_id" - ID of the ad group that contains the ad.
  , adAndroidDeepLink :: !(Maybe Text) -- ^ "android_deep_link" - Deep link URL for Android devices.
  , adCampaignId :: !(Text) -- ^ /Required/ /ReadOnly/ "campaign_id" - ID of the ad campaign that contains this ad.
  , adCarouselAndroidDeepLinks :: !(Maybe [Text]) -- ^ "carousel_android_deep_links" - Comma-separated deep links for the carousel pin on Android.
  , adCarouselDestinationUrls :: !(Maybe [Text]) -- ^ "carousel_destination_urls" - Comma-separated destination URLs for the carousel pin to promote.
  , adCarouselIosDeepLinks :: !(Maybe [Text]) -- ^ "carousel_ios_deep_links" - Comma-separated deep links for the carousel pin on iOS.
  , adCartingPlatformType :: !(Maybe Int) -- ^ /ReadOnly/ "carting_platform_type" - The vendor platform type of the carting/WTB ad.
  , adCartingProducts :: !(Maybe [CartingProduct]) -- ^ /ReadOnly/ "carting_products" - Array of carting/WTB products for the ad.
  , adClickTrackingUrl :: !(Maybe Text) -- ^ "click_tracking_url" - Tracking url for the ad clicks.
  , adCollectionItemsDestinationUrlTemplate :: !(Maybe Text) -- ^ "collection_items_destination_url_template" - Destination URL template for all items within a collections drawer.
  , adCollectionsHeaderType :: !(Maybe AdCollectionsHeaderType) -- ^ "collections_header_type"
  , adCreatedTime :: !(Maybe Int) -- ^ /ReadOnly/ "created_time" - Pin creation time. Unix timestamp in seconds.
  , adCreativeType :: !(CreativeType) -- ^ /Required/ "creative_type"
  , adCustomizableCtaType :: !(Maybe CustomizableCTAType) -- ^ "customizable_cta_type"
  , adDestinationUrl :: !(Maybe Text) -- ^ "destination_url" - Destination URL.
  , adDisclosureType :: !(Maybe DisclosureType) -- ^ "disclosure_type"
  , adDisclosureUrl :: !(Maybe Text) -- ^ "disclosure_url" - URL for a page that provides disclosures about a pharmaceutical product, such as potential side effects. Make sure the URL takes the user directly to the disclosure content and the referenced site is secure.
  , adGridClickType :: !(Maybe GridClickType) -- ^ "grid_click_type"
  , adId :: !(Text) -- ^ /Required/ "id" - The ID of this ad.
  , adIosDeepLink :: !(Maybe Text) -- ^ "ios_deep_link" - Deep link URL for iOS devices.
  , adIsCarting :: !(Maybe Bool) -- ^ "is_carting" - Is the ad a carting/WTB ad?
  , adIsCollageAcceptedTerms :: !(Maybe Bool) -- ^ "is_collage_accepted_terms" - Whether the advertiser has accepted the terms and conditions for collage ad.
  , adIsCollageSingleDestination :: !(Maybe Bool) -- ^ "is_collage_single_destination" - Whether the collage ad has a single destination url override.
  , adIsPinDeleted :: !(Maybe Bool) -- ^ "is_pin_deleted" - Is original pin deleted?
  , adIsRemovable :: !(Maybe Bool) -- ^ "is_removable" - Is pin repinnable?
  , adLeadFormId :: !(Maybe Text) -- ^ "lead_form_id" - Lead form ID for lead ad generation.
  , adName :: !(Maybe Text) -- ^ "name" - Name of the ad - 255 chars max.
  , adPinId :: !(Text) -- ^ /Required/ "pin_id" - Pin ID. This field may only be updated for draft ads.
  , adQuizPinData :: !(Maybe QuizPinData) -- ^ "quiz_pin_data" - Before creating a quiz ad, you must create an organic Pin using POST/Create Pin for each result in the quiz. Quiz ads cannot be saved by a Pinner. Quiz ad results can be saved.
  , adRejectedReasons :: !([AdDisapprovalReasons]) -- ^ /Required/ /ReadOnly/ "rejected_reasons" - Enum reason why the pin was rejected. Returned if &#x60;review_status&#x60; is \&quot;REJECTED\&quot;.
  , adRejectionLabels :: !([Text]) -- ^ /Required/ /ReadOnly/ "rejection_labels" - Text reason why the pin was rejected. Returned if &#x60;review_status&#x60; is \&quot;REJECTED\&quot;.
  , adReviewStatus :: !(AdReviewStatus) -- ^ /Required/ /ReadOnly/ "review_status" - Ad review status
  , adStatus :: !(Maybe EntityStatus) -- ^ "status"
  , adSummaryStatus :: !(PinPromotionSummaryStatus) -- ^ /Required/ /ReadOnly/ "summary_status" - Ad summary status
  , adTrackingUrls :: !(Maybe TrackingUrls) -- ^ "tracking_urls"
  , adType :: !(Text) -- ^ /Required/ /ReadOnly/ "type" - Always \&quot;ad\&quot;.
  , adUpdatedTime :: !(Maybe Int) -- ^ /ReadOnly/ "updated_time" - Last update time. Unix timestamp in seconds.
  , adViewTrackingUrl :: !(Maybe Text) -- ^ "view_tracking_url" - Tracking URL for ad impressions.
  } deriving (P.Show, P.Eq, P.Typeable)

