  { adAccountCountry :: !(Maybe Country) -- ^ "country"
  , adAccountCreatedTime :: !(Maybe Int) -- ^ /ReadOnly/ "created_time" -  Creation time. Unix timestamp in seconds.
  , adAccountCurrency :: !(Maybe Currency) -- ^ "currency"
  , adAccountId :: !(Text) -- ^ /Required/ "id"
  , adAccountName :: !(Maybe Text) -- ^ "name" - Ad account name.
  , adAccountOwner :: !(Maybe AdAccountOwner) -- ^ /ReadOnly/ "owner" - Ad account owner
  , adAccountPermissions :: !(Maybe [BusinessAccessRole]) -- ^ /ReadOnly/ "permissions"
  , adAccountTimeZone :: !(Maybe Text) -- ^ "time_zone" - The time zone of the ad account, in IANA format (e.g., \&quot;America/Los_Angeles\&quot;). Adding your local time zone lets you view your campaigns and ad reporting in your preferred time zone. Future reports will be available in both your local time zone and default UTC time zone. Historical data takes 1-2 months to backfill. Your billing and order lines will remain in UTC.
  , adAccountUpdatedTime :: !(Maybe Int) -- ^ /ReadOnly/ "updated_time"
  } deriving (P.Show, P.Eq, P.Typeable)

-- | FromJSON AdAccount
instance A.FromJSON AdAccount where
  parseJSON = A.withObject "AdAccount" $ \o ->
    AdAccount
      <$> (o .:? "country")
      <*> (o .:? "created_time")
      <*> (o .:? "currency")
      <*> (o .:  "id")
      <*> (o .:? "name")
      <*> (o .:? "owner")
      <*> (o .:? "permissions")
      <*> (o .:? "time_zone")
      <*> (o .:? "updated_time")

-- | ToJSON AdAccount
instance A.ToJSON AdAccount where
  toJSON AdAccount {..} =
   _omitNulls
      [ "country" .= adAccountCountry
      , "created_time" .= adAccountCreatedTime
      , "currency" .= adAccountCurrency
      , "id" .= adAccountId
      , "name" .= adAccountName
      , "owner" .= adAccountOwner
      , "permissions" .= adAccountPermissions
      , "time_zone" .= adAccountTimeZone
      , "updated_time" .= adAccountUpdatedTime
      ]


-- | Construct a value of type 'AdAccount' (by applying it's required fields, if any)
mkAdAccount
  :: Text -- ^ 'adAccountId' 
  -> AdAccount
mkAdAccount adAccountId =
  AdAccount
  { adAccountCountry = Nothing
  , adAccountCreatedTime = Nothing
  , adAccountCurrency = Nothing
  , adAccountId
  , adAccountName = Nothing
  , adAccountOwner = Nothing
  , adAccountPermissions = Nothing
  , adAccountTimeZone = Nothing
  , adAccountUpdatedTime = Nothing
  }

