data AdCreate = AdCreate
  { adCreateAdGroupId :: !(Text) -- ^ /Required/ "ad_group_id" - ID of the ad group that contains the ad.
  , adCreateAndroidDeepLink :: !(Maybe Text) -- ^ "android_deep_link" - Deep link URL for Android devices.
  , adCreateCarouselAndroidDeepLinks :: !(Maybe [Text]) -- ^ "carousel_android_deep_links" - Comma-separated deep links for the carousel pin on Android.
  , adCreateCarouselDestinationUrls :: !(Maybe [Text]) -- ^ "carousel_destination_urls" - Comma-separated destination URLs for the carousel pin to promote.
  , adCreateCarouselIosDeepLinks :: !(Maybe [Text]) -- ^ "carousel_ios_deep_links" - Comma-separated deep links for the carousel pin on iOS.
  , adCreateClickTrackingUrl :: !(Maybe Text) -- ^ "click_tracking_url" - Tracking url for the ad clicks.
  , adCreateCollectionItemsDestinationUrlTemplate :: !(Maybe Text) -- ^ "collection_items_destination_url_template" - Destination URL template for all items within a collections drawer.
  , adCreateCollectionsHeaderType :: !(Maybe AdCollectionsHeaderType) -- ^ "collections_header_type"
  , adCreateCreativeType :: !(CreativeType) -- ^ /Required/ "creative_type"
  , adCreateCustomizableCtaType :: !(Maybe CustomizableCTAType) -- ^ "customizable_cta_type"
  , adCreateDestinationUrl :: !(Maybe Text) -- ^ "destination_url" - Destination URL.
  , adCreateDisclosureType :: !(Maybe DisclosureType) -- ^ "disclosure_type"
  , adCreateDisclosureUrl :: !(Maybe Text) -- ^ "disclosure_url" - URL for a page that provides disclosures about a pharmaceutical product, such as potential side effects. Make sure the URL takes the user directly to the disclosure content and the referenced site is secure.
  , adCreateGridClickType :: !(Maybe GridClickType) -- ^ "grid_click_type"
  , adCreateIosDeepLink :: !(Maybe Text) -- ^ "ios_deep_link" - Deep link URL for iOS devices.
  , adCreateIsCarting :: !(Maybe Bool) -- ^ "is_carting" - Is the ad a carting/WTB ad?
  , adCreateIsCollageAcceptedTerms :: !(Maybe Bool) -- ^ "is_collage_accepted_terms" - Whether the advertiser has accepted the terms and conditions for collage ad.
  , adCreateIsCollageSingleDestination :: !(Maybe Bool) -- ^ "is_collage_single_destination" - Whether the collage ad has a single destination url override.
  , adCreateIsPinDeleted :: !(Maybe Bool) -- ^ "is_pin_deleted" - Is original pin deleted?
  , adCreateIsRemovable :: !(Maybe Bool) -- ^ "is_removable" - Is pin repinnable?
  , adCreateLeadFormId :: !(Maybe Text) -- ^ "lead_form_id" - Lead form ID for lead ad generation.
  , adCreateName :: !(Maybe Text) -- ^ "name" - Name of the ad - 255 chars max.
  , adCreatePinId :: !(Text) -- ^ /Required/ "pin_id" - Pin ID. This field may only be updated for draft ads.
  , adCreateQuizPinData :: !(Maybe QuizPinData) -- ^ "quiz_pin_data" - Before creating a quiz ad, you must create an organic Pin using POST/Create Pin for each result in the quiz. Quiz ads cannot be saved by a Pinner. Quiz ad results can be saved.
  , adCreateStatus :: !(Maybe EntityStatus) -- ^ "status"
  , adCreateTrackingUrls :: !(Maybe TrackingUrls) -- ^ "tracking_urls"
  , adCreateViewTrackingUrl :: !(Maybe Text) -- ^ "view_tracking_url" - Tracking URL for ad impressions.
  } deriving (P.Show, P.Eq, P.Typeable)

-- | FromJSON AdCreate
instance A.FromJSON AdCreate where
  parseJSON = A.withObject "AdCreate" $ \o ->
    AdCreate
      <$> (o .:  "ad_group_id")
      <*> (o .:? "android_deep_link")
      <*> (o .:? "carousel_android_deep_links")
      <*> (o .:? "carousel_destination_urls")
      <*> (o .:? "carousel_ios_deep_links")
