      <*> (o .:? "destination_url")
      <*> (o .:? "disclosure_type")
      <*> (o .:? "disclosure_url")
      <*> (o .:? "grid_click_type")
      <*> (o .:? "ios_deep_link")
      <*> (o .:? "is_carting")
      <*> (o .:? "is_collage_accepted_terms")
      <*> (o .:? "is_collage_single_destination")
      <*> (o .:? "is_pin_deleted")
      <*> (o .:? "is_removable")
      <*> (o .:? "lead_form_id")
      <*> (o .:? "name")
      <*> (o .:  "pin_id")
      <*> (o .:? "quiz_pin_data")
      <*> (o .:? "status")
      <*> (o .:? "tracking_urls")
      <*> (o .:? "view_tracking_url")

-- | ToJSON AdCreate
instance A.ToJSON AdCreate where
  toJSON AdCreate {..} =
   _omitNulls
      [ "ad_group_id" .= adCreateAdGroupId
      , "android_deep_link" .= adCreateAndroidDeepLink
      , "carousel_android_deep_links" .= adCreateCarouselAndroidDeepLinks
      , "carousel_destination_urls" .= adCreateCarouselDestinationUrls
      , "carousel_ios_deep_links" .= adCreateCarouselIosDeepLinks
      , "click_tracking_url" .= adCreateClickTrackingUrl
      , "collection_items_destination_url_template" .= adCreateCollectionItemsDestinationUrlTemplate
      , "collections_header_type" .= adCreateCollectionsHeaderType
      , "creative_type" .= adCreateCreativeType
      , "customizable_cta_type" .= adCreateCustomizableCtaType
      , "destination_url" .= adCreateDestinationUrl
      , "disclosure_type" .= adCreateDisclosureType
      , "disclosure_url" .= adCreateDisclosureUrl
      , "grid_click_type" .= adCreateGridClickType
      , "ios_deep_link" .= adCreateIosDeepLink
      , "is_carting" .= adCreateIsCarting
      , "is_collage_accepted_terms" .= adCreateIsCollageAcceptedTerms
      , "is_collage_single_destination" .= adCreateIsCollageSingleDestination
      , "is_pin_deleted" .= adCreateIsPinDeleted
      , "is_removable" .= adCreateIsRemovable
      , "lead_form_id" .= adCreateLeadFormId
      , "name" .= adCreateName
      , "pin_id" .= adCreatePinId
      , "quiz_pin_data" .= adCreateQuizPinData
      , "status" .= adCreateStatus
      , "tracking_urls" .= adCreateTrackingUrls
      , "view_tracking_url" .= adCreateViewTrackingUrl
      ]


