-- ** Board
-- | Board
data Board = Board
  { boardBoardPinsModifiedAt :: !(Maybe DateTime) -- ^ /ReadOnly/ "board_pins_modified_at" - Date and time of last board pins modified.
  , boardCollaboratorCount :: !(Maybe Int) -- ^ /ReadOnly/ "collaborator_count" - Count of collaborators on the board.
  , boardCreatedAt :: !(Maybe DateTime) -- ^ /ReadOnly/ "created_at" - Date and time of board creation.
  , boardDescription :: !(Maybe Text) -- ^ "description"
  , boardFollowerCount :: !(Maybe Int) -- ^ /ReadOnly/ "follower_count" - Board follower count.
  , boardId :: !(Text) -- ^ /Required/ /ReadOnly/ "id"
  , boardIsAdsOnly :: !(Maybe Bool) -- ^ "is_ads_only" - If set to &#x60;true&#x60;, the board will be ad-only and can store ad-only Pins.
  , boardMedia :: !(Maybe BoardMedia) -- ^ /ReadOnly/ "media" - Board media.
  , boardName :: !(Text) -- ^ /Required/ "name" -     Name of the board.      **Note:** If you create an ad-only board by setting &#x60;is_ads_only&#x60;     to &#x60;true&#x60;, the board name automatically becomes \&quot;Ad-only Pins\&quot;.
  , boardOwner :: !(Maybe BoardOwner) -- ^ /ReadOnly/ "owner"
  , boardPinCount :: !(Maybe Int) -- ^ /ReadOnly/ "pin_count" - Count of Pins on the board.
  , boardPrivacy :: !(Maybe BoardPrivacy) -- ^ "privacy" -     Privacy setting for a board. Learn more about [secret](https://help.pinterest.com/en/article/secret-boards)     boards and [protected](https://help.pinterest.com/en/business/article/protected-boards) boards.      **Note:** If you create an ad-only board by setting &#x60;is_ads_only&#x60;     to &#x60;true&#x60;, the &#x60;privacy&#x60; settng automatically becomes &#x60;PROTECTED&#x60;. 
  } deriving (P.Show, P.Eq, P.Typeable)

-- | FromJSON Board
instance A.FromJSON Board where
  parseJSON = A.withObject "Board" $ \o ->
    Board
      <$> (o .:? "board_pins_modified_at")
      <*> (o .:? "collaborator_count")
      <*> (o .:? "created_at")
      <*> (o .:? "description")
      <*> (o .:? "follower_count")
      <*> (o .:  "id")
      <*> (o .:? "is_ads_only")
      <*> (o .:? "media")
      <*> (o .:  "name")
      <*> (o .:? "owner")
      <*> (o .:? "pin_count")
      <*> (o .:? "privacy")

-- | ToJSON Board
instance A.ToJSON Board where
  toJSON Board {..} =
   _omitNulls
      [ "board_pins_modified_at" .= boardBoardPinsModifiedAt
      , "collaborator_count" .= boardCollaboratorCount
      , "created_at" .= boardCreatedAt
      , "description" .= boardDescription
      , "follower_count" .= boardFollowerCount
      , "id" .= boardId
      , "is_ads_only" .= boardIsAdsOnly
      , "media" .= boardMedia
      , "name" .= boardName
      , "owner" .= boardOwner
      , "pin_count" .= boardPinCount
      , "privacy" .= boardPrivacy
      ]


-- | Construct a value of type 'Board' (by applying it's required fields, if any)
mkBoard
  :: Text -- ^ 'boardId' 
  -> Text -- ^ 'boardName':     Name of the board.      **Note:** If you create an ad-only board by setting `is_ads_only`     to `true`, the board name automatically becomes \"Ad-only Pins\".
