  , boardFollowerCount = Nothing
  , boardId
  , boardIsAdsOnly = Nothing
  , boardMedia = Nothing
  , boardName
  , boardOwner = Nothing
  , boardPinCount = Nothing
  , boardPrivacy = Nothing
  }

