  , customerListType :: !(Maybe Text) -- ^ /ReadOnly/ "type" - Always &#x60;customerlist&#x60;.
  , customerListUpdatedTime :: !(Maybe Double) -- ^ /ReadOnly/ "updated_time" - Last update time. Unix timestamp in seconds.
