-- ** TargetingSpec
-- | TargetingSpec
-- Ad group targeting specification defining the ad group target audience. For example, `{\"APPTYPE\":[\"iphone\"], \"GENDER\":[\"male\"], \"LOCALE\":[\"en-US\"], \"LOCATION\":[\"501\"], \"MINIMUM_AGE\":\"18\", \"MAXIMUM_AGE\":\"65+\"}`
data TargetingSpec = TargetingSpec
  { targetingSpecAgeBucket :: !(Maybe [TargetingSpecAgeBucket]) -- ^ "AGE_BUCKET" - **Legacy field.** Predefined age ranges. We recommend using MINIMUM_AGE and MAXIMUM_AGE instead for more flexible targeting. Cannot be combined with MINIMUM_AGE/MAXIMUM_AGE. If neither AGE_BUCKET nor MINIMUM_AGE/MAXIMUM_AGE are specified, all ages will be targeted.
  , targetingSpecApptype :: !(Maybe [TargetingSpecAppType]) -- ^ "APPTYPE" - Allowed devices. If the APPTYPE field is missing, the default behavior in terms of ad delivery is that **All devices/apptypes** will be targeted.
  , targetingSpecAudienceExclude :: !(Maybe [Text]) -- ^ "AUDIENCE_EXCLUDE" - Excluded customer list IDs. Used to drive new customer acquisition goals. For example: [\&quot;2542620905475\&quot;]. Audience lists need to have at least 100 people with Pinterest accounts in them. If the AUDIENCE_EXCLUDE field is missing, the default behavior in terms of ad delivery is that **No users will be excluded**.
  , targetingSpecAudienceInclude :: !(Maybe [Text]) -- ^ "AUDIENCE_INCLUDE" - Targeted customer list IDs. For example: [\&quot;2542620905473\&quot;]. Audience lists need to have at least 100 people with Pinterest accounts in them Audience lists need to have at least 100 people with Pinterest accounts in them. If the AUDIENCE_INCLUDE field is missing, the default behavior in terms of ad delivery is that **All users will be included**.
  , targetingSpecGender :: !(Maybe [TargetingSpecGender]) -- ^ "GENDER" - Targeted genders. Values: [\&quot;unknown\&quot;,\&quot;male\&quot;,\&quot;female\&quot;]. If the GENDER field is missing, the default behavior in terms of ad delivery is that **All genders will be targeted**.
  , targetingSpecGeo :: !(Maybe [Text]) -- ^ "GEO" - Region codes or postal codes to include for targeting.&lt;br /&gt;&lt;br /&gt; Region codes represent broader geographical areas. Example: &lt;code&gt;US-CA&lt;/code&gt; is the region code for California in the United States.&lt;br /&gt;&lt;br /&gt; Postal codes represent more granular, specific areas. Example: &lt;code&gt;94103&lt;/code&gt; is a postal code for a specifc area in San Francisco, California, U.S.A.&lt;br /&gt;&lt;br /&gt; For each ad group, use only one of these methods, depending on which fits your targeting needs. Do not use both. For example, either specify a broader region code like &lt;code&gt;US-CA&lt;/code&gt; or a more granular postal code within that regon, such as &lt;code&gt;94103&lt;/code&gt;.&lt;br /&gt;&lt;br /&gt; You can specify multiple region codes or postal codes in an array, depending on which method you choose.&lt;br /&gt;&lt;br /&gt; Precede a region code array with the &lt;code&gt;region_codes&lt;/code&gt; key and a postal code value with the &lt;code&gt;postal_codes&lt;/code&gt; key. Examples:&lt;br /&gt;&lt;br /&gt; &lt;code&gt;\&quot;geo\&quot;: {&lt;/code&gt;&lt;br /&gt; &lt;code&gt;\&quot;region_codes\&quot;: [\&quot;US-CA\&quot;]&lt;/code&gt;&lt;br /&gt; &lt;code&gt;}&lt;/code&gt;&lt;br /&gt;&lt;br /&gt; &lt;code&gt;\&quot;geo\&quot;: {&lt;/code&gt;&lt;br /&gt; &lt;code&gt;\&quot;postal_codes\&quot;: [\&quot;94103\&quot;]&lt;/code&gt;&lt;br /&gt; &lt;code&gt;}&lt;/code&gt;&lt;br /&gt;&lt;br /&gt; For each ad group, specify at least one &lt;code&gt;GEO&lt;/code&gt; or &lt;code&gt;LOCATION&lt;/code&gt;. &lt;br /&gt;&lt;br /&gt; If you do not specifiy a &lt;code&gt;GEO&lt;/code&gt; code, only &lt;code&gt;LOCATION&lt;/code&gt; values will be targeted (See &lt;code&gt;LOCATION&lt;/code&gt; parameter in this targeting spec.).&lt;br /&gt;&lt;br /&gt; Learn how to &lt;a href&#x3D;\&quot;/docs/analytics-and-reports/ads-reporting/#get-all-available-codes-and-zones\&quot; target&#x3D;\&quot;_blank\&quot;&gt;get a current, complete list of codes&lt;/a&gt;.
  , targetingSpecGeoExclude :: !(Maybe [Text]) -- ^ "GEO_EXCLUDE" - Region codes or postal codes to exclude from the targeting inclusion area.&lt;br /&gt;&lt;br /&gt; See &lt;code&gt;GEO&lt;/code&gt; parameter in this targeting spec for rules, syntax, and other information.&lt;br /&gt;
  , targetingSpecInterest :: !(Maybe [Text]) -- ^ "INTEREST" - Array of interest object IDs. If the INTEREST field is missing, the default behavior in terms of ad delivery is that **All interests will be targeted**.
  , targetingSpecLocale :: !(Maybe [Text]) -- ^ "LOCALE" - 24 ISO 639-1 two-letter language codes. If the LOCALE field is not included in the request, all languages are targeted.
  , targetingSpecLocation :: !(Maybe [Text]) -- ^ "LOCATION" - Metropolitan codes and/or ISO-Alpha-2, two-letter country codes to include for targeting.&lt;br /&gt;&lt;br /&gt; Precede country code values with the &lt;code&gt;country_codes&lt;/code&gt; key and metro code values with &lt;code&gt;metro_codes&lt;/code&gt; key. Example:&lt;br /&gt;&lt;br /&gt; &lt;code&gt;\&quot;location\&quot;: {&lt;/code&gt;&lt;br /&gt; &lt;code&gt;\&quot;country_codes\&quot;: [\&quot;US\&quot;, \&quot;CA\&quot;],&lt;/code&gt;&lt;br /&gt; &lt;code&gt;\&quot;metro_codes\&quot;: [\&quot;501\&quot;, \&quot;602\&quot;]&lt;/code&gt;&lt;br /&gt; &lt;code&gt;}&lt;/code&gt;&lt;br /&gt;&lt;br /&gt; For each ad group, specify at least one &lt;code&gt;GEO&lt;/code&gt; or &lt;code&gt;LOCATION&lt;/code&gt; code. &lt;br /&gt;&lt;br /&gt; If you do not specify a &lt;code&gt;LOCATION&lt;/code&gt; code, only &lt;code&gt;GEO&lt;/code&gt; values will be targeted (See &lt;code&gt;GEO&lt;/code&gt; parameter in this targeting spec.).&lt;br /&gt;&lt;br /&gt; Learn how to &lt;a href&#x3D;\&quot;/docs/analytics-and-reports/ads-reporting/#get-all-available-codes-and-zones\&quot; target&#x3D;\&quot;_blank\&quot;&gt;get a current, complete list of codes&lt;/a&gt;.
  , targetingSpecLocationExclude :: !(Maybe [Text]) -- ^ "LOCATION_EXCLUDE" - Metropolitan codes and/or ISO-Alpha-2, two-letter country codes to exclude from targeting.&lt;br /&gt;&lt;br /&gt; See &lt;code&gt;LOCATION&lt;/code&gt; parameter in this targeting spec for rules, syntax, and other information.
  , targetingSpecMaximumAge :: !(Maybe Text) -- ^ "MAXIMUM_AGE" - Maximum age to target (inclusive). Values: \&quot;18\&quot;, \&quot;19\&quot;, ..., \&quot;65\&quot;, \&quot;65+\&quot;. Must be used together with &#x60;MINIMUM_AGE&#x60;. Cannot be combined with &#x60;AGE_BUCKET&#x60;. If neither &#x60;MINIMUM_AGE&#x60;/&#x60;MAXIMUM_AGE&#x60; nor &#x60;AGE_BUCKET&#x60; are specified, all ages will be targeted.
  , targetingSpecMinimumAge :: !(Maybe Text) -- ^ "MINIMUM_AGE" - Minimum age to target (inclusive). Values: \&quot;18\&quot;, \&quot;19\&quot;, ..., \&quot;65\&quot;. Note: 65+ is not allowed for minimum age. Must be used together with &#x60;MAXIMUM_AGE&#x60;. Cannot be combined with &#x60;AGE_BUCKET&#x60;. If neither &#x60;MINIMUM_AGE&#x60;/&#x60;MAXIMUM_AGE&#x60; nor &#x60;AGE_BUCKET&#x60; are specified, all ages will be targeted.
  , targetingSpecShoppingRetargeting :: !(Maybe [TargetingSpecShoppingRetargeting]) -- ^ "SHOPPING_RETARGETING" - Array of object: lookback_window [Integer]: Number of days ago to start lookback timeframe for dynamic retargeting tag_types [Array of integer]: Event types to target for dynamic retargeting exclusion_window [Integer]: Number of days ago to stop lookback timeframe for dynamic retargeting
  , targetingSpecTargetingStrategy :: !(Maybe [E'TargetingStrategy]) -- ^ "TARGETING_STRATEGY"
  } deriving (P.Show, P.Eq, P.Typeable)

-- | FromJSON TargetingSpec
instance A.FromJSON TargetingSpec where
  parseJSON = A.withObject "TargetingSpec" $ \o ->
    TargetingSpec
      <$> (o .:? "AGE_BUCKET")
      <*> (o .:? "APPTYPE")
      <*> (o .:? "AUDIENCE_EXCLUDE")
      <*> (o .:? "AUDIENCE_INCLUDE")
      <*> (o .:? "GENDER")
      <*> (o .:? "GEO")
      <*> (o .:? "GEO_EXCLUDE")
      <*> (o .:? "INTEREST")
      <*> (o .:? "LOCALE")
      <*> (o .:? "LOCATION")
      <*> (o .:? "LOCATION_EXCLUDE")
      <*> (o .:? "MAXIMUM_AGE")
      <*> (o .:? "MINIMUM_AGE")
      <*> (o .:? "SHOPPING_RETARGETING")
      <*> (o .:? "TARGETING_STRATEGY")

-- | ToJSON TargetingSpec
instance A.ToJSON TargetingSpec where
  toJSON TargetingSpec {..} =
   _omitNulls
      [ "AGE_BUCKET" .= targetingSpecAgeBucket
      , "APPTYPE" .= targetingSpecApptype
      , "AUDIENCE_EXCLUDE" .= targetingSpecAudienceExclude
      , "AUDIENCE_INCLUDE" .= targetingSpecAudienceInclude
      , "GENDER" .= targetingSpecGender
      , "GEO" .= targetingSpecGeo
      , "GEO_EXCLUDE" .= targetingSpecGeoExclude
      , "INTEREST" .= targetingSpecInterest
      , "LOCALE" .= targetingSpecLocale
      , "LOCATION" .= targetingSpecLocation
      , "LOCATION_EXCLUDE" .= targetingSpecLocationExclude
      , "MAXIMUM_AGE" .= targetingSpecMaximumAge
      , "MINIMUM_AGE" .= targetingSpecMinimumAge
      , "SHOPPING_RETARGETING" .= targetingSpecShoppingRetargeting
      , "TARGETING_STRATEGY" .= targetingSpecTargetingStrategy
      ]


