-- TrendsAgeDistribution
-- 
-- This represents a mapping from age bucket to distribution of search volume for a keyword. The sum of all values in this object should approximately be 1.
data TrendsAgeDistribution = TrendsAgeDistribution
  { trendsAgeDistributionAgeDistribution :: !(Maybe TrendsAgeBucket) -- ^ "age_distribution"
  } deriving (P.Show, P.Eq, P.Typeable)

-- | FromJSON TrendsAgeDistribution
instance A.FromJSON TrendsAgeDistribution where
  parseJSON = A.withObject "TrendsAgeDistribution" $ \o ->
    TrendsAgeDistribution
      <$> (o .:? "age_distribution")

-- | ToJSON TrendsAgeDistribution
instance A.ToJSON TrendsAgeDistribution where
  toJSON TrendsAgeDistribution {..} =
   _omitNulls
      [ "age_distribution" .= trendsAgeDistributionAgeDistribution
      ]


-- | Construct a value of type 'TrendsAgeDistribution' (by applying it's required fields, if any)
mkTrendsAgeDistribution
  :: TrendsAgeDistribution
mkTrendsAgeDistribution =
  TrendsAgeDistribution
  { trendsAgeDistributionAgeDistribution = Nothing
  }

-- ** TrendsEditorial
-- | TrendsEditorial
-- Information of the published editorial article.
data TrendsEditorial = TrendsEditorial
  { trendsEditorialBoardUrl :: !(Text) -- ^ /Required/ "board_url" - URL of the editorial board
  , trendsEditorialDescription :: !(Text) -- ^ /Required/ "description" - Description of the editorial article
  , trendsEditorialInterests :: !([Text]) -- ^ /Required/ "interests" - List of interests related to the editorial article
  , trendsEditorialPinsUrl :: !([Text]) -- ^ /Required/ "pins_url" - URL of the pins related to the editorial article
  , trendsEditorialRelatedKeywords :: !([KeywordInfo]) -- ^ /Required/ "related_keywords" - List of keywords related to the editorial article
  , trendsEditorialTitle :: !(Text) -- ^ /Required/ "title" - Title of the editorial article
  } deriving (P.Show, P.Eq, P.Typeable)

-- | FromJSON TrendsEditorial
instance A.FromJSON TrendsEditorial where
  parseJSON = A.withObject "TrendsEditorial" $ \o ->
    TrendsEditorial
      <$> (o .:  "board_url")
      <*> (o .:  "description")
      <*> (o .:  "interests")
      <*> (o .:  "pins_url")
      <*> (o .:  "related_keywords")
      <*> (o .:  "title")

-- | ToJSON TrendsEditorial
instance A.ToJSON TrendsEditorial where
  toJSON TrendsEditorial {..} =
   _omitNulls
      [ "board_url" .= trendsEditorialBoardUrl
      , "description" .= trendsEditorialDescription
      , "interests" .= trendsEditorialInterests
      , "pins_url" .= trendsEditorialPinsUrl
      , "related_keywords" .= trendsEditorialRelatedKeywords
      , "title" .= trendsEditorialTitle
      ]


-- | Construct a value of type 'TrendsEditorial' (by applying it's required fields, if any)
mkTrendsEditorial
  :: Text -- ^ 'trendsEditorialBoardUrl': URL of the editorial board
  -> Text -- ^ 'trendsEditorialDescription': Description of the editorial article
  -> [Text] -- ^ 'trendsEditorialInterests': List of interests related to the editorial article
  -> [Text] -- ^ 'trendsEditorialPinsUrl': URL of the pins related to the editorial article
  -> [KeywordInfo] -- ^ 'trendsEditorialRelatedKeywords': List of keywords related to the editorial article
  -> Text -- ^ 'trendsEditorialTitle': Title of the editorial article
  -> TrendsEditorial
mkTrendsEditorial trendsEditorialBoardUrl trendsEditorialDescription trendsEditorialInterests trendsEditorialPinsUrl trendsEditorialRelatedKeywords trendsEditorialTitle =
  TrendsEditorial
  { trendsEditorialBoardUrl
  , trendsEditorialDescription
  , trendsEditorialInterests
  , trendsEditorialPinsUrl
  , trendsEditorialRelatedKeywords
  , trendsEditorialTitle
  }

