-- ** ActionType

-- | Enum of 'Text' .
-- Ad group billable event type. For update, only draft ad groups may update billable event.
data ActionType
  = ActionType'CLICKTHROUGH -- ^ @"CLICKTHROUGH"@
  | ActionType'IMPRESSION -- ^ @"IMPRESSION"@
  | ActionType'VIDEO_V_50_MRC -- ^ @"VIDEO_V_50_MRC"@
  deriving (P.Show, P.Eq, P.Typeable, P.Ord, P.Bounded, P.Enum)

instance A.ToJSON ActionType where toJSON = A.toJSON . fromActionType
instance A.FromJSON ActionType where parseJSON o = P.either P.fail (pure . P.id) . toActionType =<< A.parseJSON o
instance WH.ToHttpApiData ActionType where toQueryParam = WH.toQueryParam . fromActionType
instance WH.FromHttpApiData ActionType where parseQueryParam o = WH.parseQueryParam o >>= P.left T.pack . toActionType
instance MimeRender MimeMultipartFormData ActionType where mimeRender _ = mimeRenderDefaultMultipartFormData

-- | unwrap 'ActionType' enum
fromActionType :: ActionType -> Text
fromActionType = \case
  ActionType'CLICKTHROUGH -> "CLICKTHROUGH"
  ActionType'IMPRESSION -> "IMPRESSION"
  ActionType'VIDEO_V_50_MRC -> "VIDEO_V_50_MRC"

-- | parse 'ActionType' enum
toActionType :: Text -> P.Either String ActionType
toActionType = \case
  "CLICKTHROUGH" -> P.Right ActionType'CLICKTHROUGH
  "IMPRESSION" -> P.Right ActionType'IMPRESSION
  "VIDEO_V_50_MRC" -> P.Right ActionType'VIDEO_V_50_MRC
  s -> P.Left $ "toActionType: enum parse failure: " P.++ P.show s


