-- ** ProductCategoryRegion

-- | Enum of 'Text'
data ProductCategoryRegion
  = ProductCategoryRegion'US -- ^ @"US"@
  | ProductCategoryRegion'GBIE -- ^ @"GB+IE"@
  | ProductCategoryRegion'CA -- ^ @"CA"@
  deriving (P.Show, P.Eq, P.Typeable, P.Ord, P.Bounded, P.Enum)

instance A.ToJSON ProductCategoryRegion where toJSON = A.toJSON . fromProductCategoryRegion
instance A.FromJSON ProductCategoryRegion where parseJSON o = P.either P.fail (pure . P.id) . toProductCategoryRegion =<< A.parseJSON o
instance WH.ToHttpApiData ProductCategoryRegion where toQueryParam = WH.toQueryParam . fromProductCategoryRegion
instance WH.FromHttpApiData ProductCategoryRegion where parseQueryParam o = WH.parseQueryParam o >>= P.left T.pack . toProductCategoryRegion
instance MimeRender MimeMultipartFormData ProductCategoryRegion where mimeRender _ = mimeRenderDefaultMultipartFormData

-- | unwrap 'ProductCategoryRegion' enum
fromProductCategoryRegion :: ProductCategoryRegion -> Text
fromProductCategoryRegion = \case
  ProductCategoryRegion'US -> "US"
  ProductCategoryRegion'GBIE -> "GB+IE"
  ProductCategoryRegion'CA -> "CA"

-- | parse 'ProductCategoryRegion' enum
toProductCategoryRegion :: Text -> P.Either String ProductCategoryRegion
toProductCategoryRegion = \case
  "US" -> P.Right ProductCategoryRegion'US
  "GB+IE" -> P.Right ProductCategoryRegion'GBIE
  "CA" -> P.Right ProductCategoryRegion'CA
  s -> P.Left $ "toProductCategoryRegion: enum parse failure: " P.++ P.show s


