-- ** ReportingTimeZone

-- | Enum of 'Text' .
-- Specify the timezone to be applied for the reporting.
data ReportingTimeZone
  = ReportingTimeZone'PINTEREST_TIME_ZONE -- ^ @"PINTEREST_TIME_ZONE"@
  | ReportingTimeZone'AD_ACCOUNT_TIME_ZONE -- ^ @"AD_ACCOUNT_TIME_ZONE"@
  deriving (P.Show, P.Eq, P.Typeable, P.Ord, P.Bounded, P.Enum)

instance A.ToJSON ReportingTimeZone where toJSON = A.toJSON . fromReportingTimeZone
instance A.FromJSON ReportingTimeZone where parseJSON o = P.either P.fail (pure . P.id) . toReportingTimeZone =<< A.parseJSON o
instance WH.ToHttpApiData ReportingTimeZone where toQueryParam = WH.toQueryParam . fromReportingTimeZone
instance WH.FromHttpApiData ReportingTimeZone where parseQueryParam o = WH.parseQueryParam o >>= P.left T.pack . toReportingTimeZone
instance MimeRender MimeMultipartFormData ReportingTimeZone where mimeRender _ = mimeRenderDefaultMultipartFormData

-- | unwrap 'ReportingTimeZone' enum
fromReportingTimeZone :: ReportingTimeZone -> Text
fromReportingTimeZone = \case
  ReportingTimeZone'PINTEREST_TIME_ZONE -> "PINTEREST_TIME_ZONE"
  ReportingTimeZone'AD_ACCOUNT_TIME_ZONE -> "AD_ACCOUNT_TIME_ZONE"

-- | parse 'ReportingTimeZone' enum
toReportingTimeZone :: Text -> P.Either String ReportingTimeZone
toReportingTimeZone = \case
  "PINTEREST_TIME_ZONE" -> P.Right ReportingTimeZone'PINTEREST_TIME_ZONE
  "AD_ACCOUNT_TIME_ZONE" -> P.Right ReportingTimeZone'AD_ACCOUNT_TIME_ZONE
  s -> P.Left $ "toReportingTimeZone: enum parse failure: " P.++ P.show s


